#include <stdio.h>
#include <stdlib.h>

#define MAXN 100001

typedef struct Node {
    int vertex;
    struct Node* next;
} Node;

Node* adj[MAXN];
int dist[MAXN];
int queue[MAXN];
int front, rear;

void addEdge(int u, int v) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->vertex = v;
    newNode->next = adj[u];
    adj[u] = newNode;
}

void bfs(int start, int n) {
    for (int i = 1; i <= n; i++) dist[i] = -1;
    front = rear = 0;

    dist[start] = 0;
    queue[rear++] = start;

    while (front < rear) {
        int u = queue[front++];
        Node* temp = adj[u];
        while (temp) {
            int v = temp->vertex;
            if (dist[v] == -1) {
                dist[v] = dist[u] + 1;
                queue[rear++] = v;
            }
            temp = temp->next;
        }
    }
}

int main() {
    int n, m;
    scanf("%d %d", &n, &m);

    for (int i = 0; i < m; i++) {
        int u, v;
