int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    int *u = (int *)malloc(n * sizeof(int));
    int **adj = (int **)malloc(n * sizeof(int *));
    int *deg = (int *)malloc(n * sizeof(int));

    for (int i = 0; i < n; i++) {
        int id, k;
        scanf("%d %d", &id, &k);
        u[i] = id;
        deg[i] = k;
        adj[i] = (int *)malloc(k * sizeof(int));
        for (int j = 0; j < k; j++) {
            scanf("%d", &adj[i][j]);
        }
    }

    int *dist = (int *)malloc((n + 1) * sizeof(int));
    for (int i = 1; i <= n; i++) dist[i] = -1;

    Queue q;
    q.data = (int *)malloc((n + 5) * sizeof(int));
    q.head = q.tail = 0;

    dist[1] = 0;
    q.data[q.tail++] = 1;

    while (q.head < q.tail) {
        int v = q.data[q.head++];

        int idx = -1;
        for (int i = 0; i < n; i++) {
            if (u[i] == v) {
                idx = i;
                break;
            }
        }
        if (idx == -1) continue;

        for (int i = 0; i < deg[idx]; i++) {
            int to = adj[idx][i];
            if (dist[to] == -1) {
                dist[to] = dist[v] + 1;
                q.data[q.tail++] = to;
            }
        }
    }

    for (int i = 1; i <= n; i++) {
        printf("%d %d\n", i, dist[i]);
    }

    for (int i = 0; i < n; i++) free(adj[i]);
    free(adj);
    free(u);
    free(deg);
    free(dist);
    free(q.data);

    return 0;
}

